<?php
if(!defined('ABSPATH'))exit;
function eicr_mojibake_score($value){return preg_match_all('/[\x{00C3}\x{00C2}\x{00E2}\x{00F0}\x{FFFD}]/u',(string)$value,$matches);}
function eicr_utf8_codepoint($char){$bytes=array_values(unpack('C*',$char));$first=$bytes[0]??0;if($first<128)return$first;if(($first&224)===192)return(($first&31)<<6)|(($bytes[1]??0)&63);if(($first&240)===224)return(($first&15)<<12)|((($bytes[1]??0)&63)<<6)|(($bytes[2]??0)&63);return(($first&7)<<18)|((($bytes[1]??0)&63)<<12)|((($bytes[2]??0)&63)<<6)|(($bytes[3]??0)&63);}
function eicr_utf8_from_codepoint($cp){if($cp<128)return chr($cp);if($cp<2048)return chr(192|($cp>>6)).chr(128|($cp&63));if($cp<65536)return chr(224|($cp>>12)).chr(128|(($cp>>6)&63)).chr(128|($cp&63));return chr(240|($cp>>18)).chr(128|(($cp>>12)&63)).chr(128|(($cp>>6)&63)).chr(128|($cp&63));}
function eicr_cp1252_bytes($value){$result='';foreach(preg_split('//u',$value,-1,PREG_SPLIT_NO_EMPTY)as$char){$byte=function_exists('iconv')?@iconv('UTF-8','Windows-1252',$char):false;if($byte===false||$byte===''){$cp=eicr_utf8_codepoint($char);if($cp>=128&&$cp<=159)$byte=chr($cp);else return'';}$result.=$byte;}return$result;}
function eicr_make_mojibake($value){$result='';for($i=0,$length=strlen($value);$i<$length;$i++){$byte=$value[$i];$char=function_exists('iconv')?@iconv('Windows-1252','UTF-8',$byte):false;$result.=($char===false||$char==='')?eicr_utf8_from_codepoint(ord($byte)):$char;}return$result;}
function eicr_repair_mojibake_string($value){if(!is_string($value)||$value===''||!eicr_mojibake_score($value))return$value;$current=$value;for($pass=0;$pass<3;$pass++){$candidate='';$candidate=eicr_cp1252_bytes($current);if(!is_string($candidate)||$candidate===''||!preg_match('//u',$candidate))break;if(eicr_mojibake_score($candidate)>eicr_mojibake_score($current))break;$current=$candidate;if(!eicr_mojibake_score($current))break;}$symbols=["\u{00A3}","\u{2013}","\u{2014}","\u{2018}","\u{2019}","\u{201C}","\u{201D}","\u{2026}","\u{2192}","\u{2713}","\u{00A9}","\u{00AE}","\u{00A0}"];foreach($symbols as$good){$bad1=eicr_make_mojibake($good);$bad2=$bad1!==''?eicr_make_mojibake($bad1):'';if($bad2!=='')$current=str_replace($bad2,$good,$current);if($bad1!=='')$current=str_replace($bad1,$good,$current);}return$current;}
function eicr_repair_mojibake_value($value){if(is_string($value))return eicr_repair_mojibake_string($value);if(is_array($value)){foreach($value as$key=>$item)$value[$key]=eicr_repair_mojibake_value($item);}return$value;}
function eicr_run_utf8_database_repair(){if(get_option('eicr_utf8_repair_version')==='4')return;$ids=get_posts(['post_type'=>['eicr_service','eicr_order','eicr_quote','eicr_review'],'post_status'=>'any','numberposts'=>-1,'fields'=>'ids','orderby'=>'ID','order'=>'ASC']);foreach($ids as$id){$post=get_post($id);if(!$post)continue;$title=eicr_repair_mojibake_string($post->post_title);$content=eicr_repair_mojibake_string($post->post_content);$excerpt=eicr_repair_mojibake_string($post->post_excerpt);if($title!==$post->post_title||$content!==$post->post_content||$excerpt!==$post->post_excerpt)wp_update_post(['ID'=>$id,'post_title'=>$title,'post_content'=>$content,'post_excerpt'=>$excerpt]);$all_meta=get_post_meta($id);foreach($all_meta as$key=>$values){foreach($values as$raw){$value=maybe_unserialize($raw);$fixed=eicr_repair_mojibake_value($value);if($fixed!==$value)update_post_meta($id,$key,$fixed,$value);}}}$settings=(array)get_option('eicr_settings',[]);foreach(['phone','email','invoice_email','address','bank_name','bank_account_name','seo_description']as$key)if(isset($settings[$key]))$settings[$key]=eicr_repair_mojibake_string($settings[$key]);update_option('eicr_settings',$settings,false);foreach(['blogname','blogdescription']as$key){$value=get_option($key);$fixed=eicr_repair_mojibake_string($value);if($fixed!==$value)update_option($key,$fixed);}update_option('blog_charset','UTF-8');update_option('eicr_utf8_repair_version','4',false);wp_cache_flush();if(function_exists('w3tc_flush_all'))w3tc_flush_all();if(function_exists('rocket_clean_domain'))rocket_clean_domain();if(function_exists('wpfc_clear_all_cache'))wpfc_clear_all_cache(true);if(function_exists('sg_cachepress_purge_cache'))sg_cachepress_purge_cache();if(class_exists('autoptimizeCache'))autoptimizeCache::clearall();do_action('litespeed_purge_all');}
add_action('init','eicr_run_utf8_database_repair',99);
add_filter('wp_headers',function($headers){$headers['Content-Type']='text/html; charset=UTF-8';return$headers;},99);
